/// <summary>
/// Handles the click event of the OK button.
/// </summary>
public void clicked()
{
    int                 currentCounter;
    int                 numIter = NumOfIteration.value();
    InventTable         inventTable;
    InventTableModule   inventTableModule;

    if (numIter <= 0)
    {
        info("@MET:ValidItemAndIteration");
        return;
    }

    ttsbegin;
    while select forupdate Price, METOrigPrice from inventTableModule
        order by inventTableModule.ItemId
    {
        currentCounter++;

        if (currentCounter > numIter)
        {
            break;
        }

        inventTableModule.METOrigPrice  = inventTableModule.Price;
        inventTableModule.Price         += 1;

        inventTableModule.update();
    }
    ttscommit;

    super();
}

/// <summary>
/// Handles the click event of the Restore button.
/// </summary>
public void clicked()
{
    int                 numIter = NumOfIteration.value();
    int                 currentCounter;
    InventTableModule   inventTableModule;

    if (numIter <= 0)
    {
        info("@MET:ValidItemAndIteration");
        return;
    }

    ttsbegin;
    while select forupdate Price, METOrigPrice from inventTableModule
        order by inventTableModule.ItemId
        where inventTableModule.METOrigPrice != 0
    {
        currentCounter++;

        if (currentCounter > numIter)
        {
            break;
        }

        inventTableModule.Price         = inventTableModule.METOrigPrice;
        inventTableModule.METOrigPrice  = 0;
        inventTableModule.update();
    }
    ttscommit;

    info("@MET:ItemPriceRestored");

    super();
}
